GLOBAL
  fpg_knight = 0;
  fnt_pixel = 0;
  snd_salto = 0;
  snd_moneda = 0;
  snd_herido = 0;
  gold = 0;
  hp = 100;
  gravity = 0.6;

LOCAL
  speed = 4;
  vx = 0;
  vy = 0;
  on_ground = 0;

BEGIN
  set_mode(m640x480);
  set_fps(60);
  screen_color(rgb(15, 23, 42));

  // Carga explícita de sprites FPG, fuentes FNT y sonidos WAV (DIV Games Studio)
  fpg_knight = load_fpg("knight.fpg");
  fnt_pixel = load_fnt("medieval.fnt");
